def type_to_dict(typ: type) -> TypeDict:
    if is_typed_dict(typ):
        return typed_dict_to_dict(typ)
    if is_any(typ):
        return {'module': 'typing', 'qualname': 'Any'}
    if is_union(typ):
        args = typ.__args__
        elem_types = [type_to_dict(arg) for arg in args]
        return {'module': 'typing', 'qualname': 'Union', 'elem_types': elem_types}
    if is_generic(typ):
        qualname = qualname_of_generic(typ)
        args = typ.__args__ if typ.__args__ is not None else []
        elem_types = [type_to_dict(arg) for arg in args]
        return {'module': 'typing', 'qualname': qualname, 'elem_types': elem_types}
    return {'module': typ.__module__, 'qualname': typ.__qualname__}

def type_from_dict(d: TypeDict) -> type:
    if d.get('is_typed_dict'):
        return typed_dict_from_dict(d)
    module = d['module']
    qualname = d['qualname']
    elem_types_raw = d.get('elem_types', None)
    if elem_types_raw is not None:
        elem_types = [type_from_dict(e) for e in elem_types_raw]
    else:
        elem_types = None
    if module == '__builtin__' or module == 'builtins':
        if qualname in _HIDDEN_BUILTIN_TYPES:
            typ = _HIDDEN_BUILTIN_TYPES[qualname]
        else:
            typ = get_name_in_module(module, qualname, _HIDDEN_BUILTIN_TYPES)
    else:
        typ = get_name_in_module(module, qualname, _HIDDEN_BUILTIN_TYPES)
    if not isinstance(typ, type) and not is_any(typ) and not is_generic(typ) and not is_union(typ):
        raise InvalidTypeError(
            f"Attribute specified by {module}.{qualname} is not a type: {typ!r}"
        )
    if elem_types is not None:
        typ = typ[tuple(elem_types)]
    return typ
